/**
 * 中国地形区与山脉教学数据（v0.0.1）
 *
 * 人工编写的部分：id / name / 分组 / 典型海拔 / 讲解文本。
 * 由真实 DEM 生成并**反向校验**的部分：地形区边界 ring（多边形内海拔中位数
 * 必须落在 tol 区间、区内还埋了真实城市当哨兵）、山脉走向 line（在 DEM 上
 * 实测校准过脊线，并按国界裁到境内）。
 *
 * 为什么要这么较劲：这类数据错了是**静默的教学错误** —— 隆起效果照常出现，
 * 只是隆起在了错的地方，肉眼对着小地图根本看不出来。
 *
 * ⚠️ 本文件由 .workbuddy/tmp/cnterrain/build_regions.py 生成，请勿手改。
 *    改数据请改 regions_source.py，再跑 fit_ridges.py + build_regions.py。
 */

export type AreaKind = "plateau" | "basin" | "plain";

export interface AreaDef {
  id: string;
  name: string;
  kind: AreaKind;
  group: string;
  /** 在区域 id 位图里的编号（1..N，0 = 不属于任何地形区） */
  gridId: number;
  /** 边界多边形（经纬度），用于画轮廓与「提示」高亮 */
  ring: [number, number][];
  /** 卡片锚点：拖对了落在这附近 */
  anchor: [number, number];
  /** 典型海拔（米） */
  elevation: number;
  /** 由 DEM 实测得到的合理海拔区间，供回归测试用 */
  tol: [number, number];
  color: string;
  blurb: string;
}

export interface RangeDef {
  id: string;
  name: string;
  core: boolean;
  /** 山脊走向折线（经纬度），已按国界裁到境内 */
  line: [number, number][];
  anchor: [number, number];
  color: string;
  blurb: string;
}

